import base64, hashlib, json, math, pathlib, sys, zipfile
from PIL import Image, ImageDraw, ImageFont, ImageFilter

root, capture_path, car_path, old_apk = (pathlib.Path(v) for v in sys.argv[1:5])
root.mkdir(exist_ok=False)
RESAMPLE = Image.Resampling.BICUBIC
FONT = 'C:/Windows/Fonts/arialbd.ttf'
FPS = 30
PLATE = '50E-389.20'

def clamp(x):
    return max(0.0, min(1.0, x))

def smooth(x):
    x = clamp(x)
    return x*x*(3-2*x)

def fit(image, width):
    return image.resize((width, round(image.height * width / image.width)), Image.Resampling.LANCZOS)

def natural_alpha(image):
    assert image.mode == 'RGBA' and image.getchannel('A').getextrema() == (0,255)
    return image

def branded_headset(image):
    # Supply the legible production insignia as a separate composited layer.
    label = Image.new('RGBA', (112, 124))
    d = ImageDraw.Draw(label)
    d.ellipse((20, 17, 92, 107), fill=(14, 25, 34, 252))
    d.text((56, 62), 'TiG', font=ImageFont.truetype(FONT, 34),
           fill=(150, 245, 255, 255), anchor='mm')
    label = label.rotate(20, resample=RESAMPLE, expand=True)
    image.alpha_composite(label, (249-label.width//2, 596-label.height//2))
    return image

def strip_warp(image, beat):
    # Warp the camera and arms together so hands stay attached to the camera and sleeves.
    w,h=image.size
    meshes=[]
    change = 0.36*math.pi
    grids = [(y, beat*math.exp(-((y-.55*h)/(.25*h))**2) *
                 math.sin(change + math.pi*y/h)) for y in range(0,h,8)]
    grids.append((h,0.0))
    for (y0,d0),(y1,d1) in zip(grids, grids[1:]):
        meshes.append(((0,y0,w,y1),(0,y0+d0,0,y1+d1,w,y1+d1,w,y0+d0)))
    return image.transform(image.size, Image.Transform.MESH, meshes, resample=RESAMPLE)

def draw_flash(canvas, x, y, strength):
    effect = Image.new('RGBA', (144,144))
    d=ImageDraw.Draw(effect)
    for radius, opacity in ((61,24),(43,51),(28,96),(14,164),(5,250)):
        d.ellipse((72-radius,72-radius,72+radius,72+radius),
                  fill=(242,250,255,round(opacity*strength)))
    effect=effect.filter(ImageFilter.GaussianBlur(3))
    d = ImageDraw.Draw(effect)
    points=[]
    for i in range(8):
        angle=i*math.pi/4
        radius=(42 if i%2==0 else 5)*(0.65+strength*.35)
        points.append((72+math.cos(angle)*radius,72+math.sin(angle)*radius))
    d.polygon(points, fill=(255,250,219,round(strength*238)))
    canvas.alpha_composite(effect,(x-72,y-72))

capture = fit(branded_headset(natural_alpha(Image.open(capture_path))), 620)
capture_frames=[]
for i in range(42):
    t=i/FPS
    ready=smooth(t/.28)
    recoil=math.exp(-((t-.395)/.047)**2)
    # Starts already recognizable, settles with the camera held visibly at the end.
    displacement=-30*(1-ready)-4*recoil+1.5*math.sin(2.1*t)
    frame=Image.new('RGBA',(720,640))
    pose=strip_warp(capture, displacement).rotate((1-ready)*-3.7+1.1*recoil,
