    x=(720-pose.width)//2+round(5*(1-ready))
    y=640-pose.height-14+round(7*(1-ready))
    frame.alpha_composite(pose,(x,y))
    flash=max(0.0, 1.0-abs((t-.383)/.055))
    if flash:
