    capture_frames.append(frame)

def add_plate(car):
    plate = Image.new('RGBA',(186,58))
    d=ImageDraw.Draw(plate)
    d.text((93,29), PLATE, font=ImageFont.truetype(FONT,33),
           fill=(21,23,18,255), anchor='mm', stroke_width=0)
    plate=plate.rotate(2.0,RESAMPLE,expand=True)
    car.alpha_composite(plate,(1553-plate.width//2,609-plate.height//2))
    return car

vehicle = fit(add_plate(natural_alpha(Image.open(car_path))), 720)
scale=vehicle.width/1774
wheels=[]
for cx,cy,rx,ry in [(195,644,65,97),(986,679,82,111)]:
    left,top=round((cx-rx)*scale),round((cy-ry)*scale)
    ww,hh=round(2*rx*scale),round(2*ry*scale)
    square=vehicle.crop((left,top,left+ww,top+hh)).resize((120,120),RESAMPLE)
    mask=Image.new('L',(120,120))
    ImageDraw.Draw(mask).ellipse((4,4,115,115),fill=255)
    mask=mask.filter(ImageFilter.GaussianBlur(1.9)).resize((ww,hh),Image.Resampling.LANCZOS)
    wheels.append((left,top,ww,hh,square,mask))

drive_frames=[]
positions=[]
for i in range(108):
    t=i/(108-1)
    phase = .14*smooth(t/.24)+.72*t+.14*smooth((t-.76)/.24)
    x=42+round(446*phase)
    y=58+round(.9*math.sin(t*math.pi*7)*math.sin(t*math.pi))
    frame=Image.new('RGBA',(1280,450))
    car=vehicle.copy()
    for left,top,w,h,square,mask in wheels:
        angle=-math.degrees((x-42)/max(w,h)*1.44)
        rim=square.rotate(angle,RESAMPLE).resize((w,h),RESAMPLE)
        car.paste(rim,(left,top),mask)
    shadow=Image.new('RGBA',(780,53))
    ImageDraw.Draw(shadow).ellipse((37,12,748,37),fill=(5,8,12,70))
    shadow=shadow.filter(ImageFilter.GaussianBlur(8))
    frame.alpha_composite(shadow,(x-30,y+vehicle.height-31))
