assert positions==sorted(positions) and positions[-1]-positions[0]>=440

def save_webp(frames, path):
    times=[round((i+1)*1000/FPS)-round(i*1000/FPS) for i in range(len(frames))]
    frames[0].save(path, format='WEBP', append_images=frames[1:], save_all=True,
        duration=times, loop=1, quality=90, alpha_quality=100, method=4)
    with Image.open(path) as preview:
        assert preview.is_animated and preview.size==frames[0].size
        n=preview.n_frames
        durations=[]
        for i in range(n):
            preview.seek(i)
            preview.load()
            durations.append(preview.info['duration'])
        assert sum(durations)==sum(times) and n>=len(frames)*.88
        assert preview.mode=='RGBA'
    return dict(frames=n, ms=sum(durations), size=frames[0].size,
                sha=hashlib.sha256(path.read_bytes()).hexdigest())

